from flask import Flask, request

app = Flask(__name__)

def make_response(user_input):
    return f'''
    <h1>Here's a story:</h1>
    {user_input}
    '''

@app.route('/story', methods=['GET'])
def story():
    user_input = request.args.get('q')
    return make_response(user_input)

def process_input(input_data):
    input_list = input_data.split('\n')
    result_dict = {}
    for line in input_list:
        key, value = line.split('=')
        key = escape_key(key)
        value = escape_value(value)
        result_dict[key] = value

    return result_dict

def escape_key(key):
    key = html.escape(key)
    key = key.replace('&equals;', '=')

    return key

def escape_value(value):
    value = html.escape(value)
    if '&' in value:
        split_values = value.split('&')
        new_split_values = []
        for val in split_values:
            if 'equals' in val:
                new_split_values.append(val)
            else:
                new_split_values.append(html.escape(val))
        value = '&'.join(new_split_values)

    return value

