def handle_login(login_data):
    username = login_data['username']
    password = login_data['password']

    user = db.get_user(username)
    if user and user.password == hashing.hash(password):
        return {'status': 'success'}

def handle_register(register_data):
    username = register_data['username']
    password = register_data['password']

    user = User(username, password)

    db.insert_user(user)

    return {'status': 'success'}

def get_user_info(request):
    auth = request.authorization
    username = auth.get('username')

    user = db.get_user(username)

    user_info = {
        'username': user.username,
        'email': user.email,
        'age': user.age
    }

    return user_info

def process_request(request):
    method = request.method

    if request.path == '/login':
        if method == 'POST':
            login_data = json.loads(request.body)
            return handle_login(login_data)

        elif request.path == '/register':
            if method == 'POST':
                register_data = json.loads(request.body)
                return handle_register(register_data)

        elif request.path == '/info':
            if method == 'GET':
                return get_user_info(request)

