import os

def get_path(filename):
    return '../' + filename

def create_tmp_file(filename):
    path = get_path(filename)
    dir_name = os.path.dirname(os.path.abspath(path))

    if not os.path.exists(dir_name):
        os.makedirs(dir_name)

    os.chmod(dir_name, 0o777)

