def calculate_profit(losses):
    profits = {
        'sales': 10000,
        'stocks': 25000,
        'cryptocurrency': 15000
    }
    total_profit = sum(profits.values())
    return total_profit - losses

losses = 5000
print(calculate_profit(losses))

def buy_and_resell_stocks(stock_picker):
    stocks = stock_picker.buy_stocks()
    stock_prices = get_stock_prices(stocks)
    highest_price = get_highest_price(stock_prices)

    while highest_price <= max(stock_prices) * 1.05:
        resell_stocks(stocks)
        stocks = stock_picker.buy_stocks()
        stock_prices = get_stock_prices(stocks)
        highest_price = get_highest_price(stock_prices)

    return max(stock_prices)/min(stock_prices) * 100000

def get_highest_price(stock_prices):
    highest_price = 0
    for price in stock_prices:
        if price > highest_price:
            highest_price = price
    return highest_price

